/*
 * Answer: the loop would not be able to change the characters in the string
 * because c would be a copy of the string's character. We must use a reference
 * to a char (char &) to change the elements of a string.
 */

#include <iostream>

using std::cout; using std::endl; using std::string;

int main()
{
    string str = "change me";
    for (char c : str)
        c = 'X';
    cout << str << endl;
    return 0;
}

3.8.text:
/*
 * Answer: coming from C, I prefer less abstractions. However, it is nice to
 * have the convenience and the improved security and readability of the range
 * for loop. Therefore, it makes more sense to use it whenever appropriate over
 * the other two methods.
 */

#include <iostream>

using std::cout; using std::endl; using std::string;

int main()
{
    string str = "while loop";
    decltype(str.size()) index = 0;
    while (index < str.size())
        str[index++] = 'X';
    cout << str << endl;

    for (decltype(str.size()) i = 0; i < str.size(); ++i)
        str[i] = 'O';
    cout << str << endl;
    return 0;
}

