    std::string string1 = "Hello!";
    std::string string2 = "hello, world!";

    if (string1 < string2)
        std::cout << "string1 < string2\n";
    else if (string1 > string2)
        std::cout << "string1 > string2\n";
    else
        std::cout << "string1 == string2\n";
    // C-Style string
    char str1[] = "Hello!";
    char str2[] = "Hello, world!";
    if (strcmp(str1, str2) < 0)
        std::cout << "str1 < str2\n";
    else if (strcmp(str1, str2) > 0)
        std::cout << "str1 > str2\n";
    else
        std::cout << "str1 == str2\n";
    return 0;
}

